namespace OpenTPW;

/// <summary>
/// The path builder's approximation register (docs/PATHS.md; docs/reverse/PATH-plan.md §10). Each entry is
/// tagged <c>[APPROX:PATH-NNN]</c> at its code site and names the plan's unknown in its first word. Everything
/// else in the path builder is traced from the Mac binary (BIN labels at the code sites).
/// </summary>
public static class PathApproximations
{
	public static readonly IReadOnlyList<(string Id, string Rule)> Entries = new[]
	{
		("PATH-001", "PATH-ENTER: a left click on an object-less cell (hover state 2, help 441) or a path cell (state 1, help 442) enters the path tool (tp.exe click dispatch 0x4879d0 builds the tool object 0x46c580(1), whose enter 0x46d5a0 calls SetMode(1) 0x52f200); the click's release sets that cell as the start only when the start check 0x535670(1, 0) does not refuse it (0x527222..0x5272b8), else the tool stays on without a start; OpenTPW instead refuses to enter when CheckCell fails, and the release-time ghost gate (0x524a63) and the re-preview while game+36 is set (0x5249b6) are not modelled"),
		("PATH-004", "PATH-CONNECT: the path-to-path links are traced and match (tp.exe 0x5348d0 mode 1: each cardinal neighbour of type 1 gets the back bit and the new cell the forward bit, 0x534976..0x534fb4, directions from the vectors set up at 0x4d9a60); not modelled: the OR into existing link bytes (OpenTPW replaces the cell's own), links to type-9/10 neighbours gated by their +0xd link, the diagonal bits 2/8/0x20/0x80 and their clean-up beside type-3/9 links (0x53518b), the type-3 to type-1 conversion at entry (0x534906) and the queue-neighbour refresh with cat_ui 139 (AUDIO-023)"),
		("PATH-005", "PATH-REMOVE: the forced path removal (a = b = 0, NoModify respected, no refund) is the original's area clear (tool mode 0x3a from the Delete key handler 0x40c5e0: two clicks span a rectangle and 0x52bdd0 calls ClearCell 0x5367a0(0, 0) on every type-1 cell, 0x52c11f), which Remove matches; OpenTPW's remove tool is one click that clears an object, else a queue cell, else a path cell, while the original's rectangle removes only objects wholly inside it and type-1 path cells and leaves queue and type-10 cells"),
		("PATH-006", "PATH-SLOPE: no slope or height test, as in the original (tp.exe LayLine 0x536100, SetCell 0x532fc0 reads heights only for the ghost, validator 0x535670 has no float operation, SetCellType 0x5346d0); the object terrain rule OpenTPW applies (water, blocked, entrance area, fixed walkway, holes) stands in for the original's cell types and ownership: map init 0x536490 types only hole cells (2, 0x1e, 7, refused by type) and leaves every other non-InitialPath cell type 0 with the unowned flag 0x40 (PATH-007)"),
		("PATH-007", "PATH-LAND: no cell gets the unowned flag 0x40 (every in-bounds cell counts as owned); the original sets 0x40 on every non-InitialPath cell at level load (tp.exe 0x536490 from 0x52f050), clears it inside the park fence that 0x5323f0 lays from the level's outline table 0x784e3c anchored on the gate (fill 0x531040/0x5311c0 plus a strip at the gate), refuses 0x40 cells for paths (0x535670) and saves the flags as mFlags (0x4d0b30); OpenTPW decodes neither the outline nor the saved flags, and Buy Land (tool 0x39, 0x5327e0) is not modelled"),
		("PATH-008", "PATH-CODE8: path over any queue cell is refused; the original's validator returns code 8 for a queue end (one link whose neighbour is a queue; tp.exe 0x535670 at 0x535d00), and code 8 is not a refusal: the start check (0x527280) and the ghost accept it, and the commit's SetCellType (0x5346d0; rule 0x535600 allows type 1 over type 3) turns the queue end into a charged path cell; OpenTPW has no queue-to-path conversion"),
		("PATH-009", "PATH-FREE: the path tool charges Costs.PathCell through Spend, which does nothing while bank +0x114 is 0 (tp.exe 0x4d01f0); OpenTPW takes 'no park economy' for that state; the free byte (tp.exe 0x8186d4, Mac data:0x7de2d) zeroes the path and queue cost in SetCellType (0x534717, 0x53472c) but is set only in the mode-4 and mode-59 placement branches (0x5235d4, 0x523967, 0x524b4a, 0x5253e9), never by the path tool; open: what bank +0x114 is"),
		("PATH-013", "PATH-PAUSE: while the pause menu is shown the park takes no tool clicks, as in the original (tp.exe gate 0x48c8d0 reads the pause-menu object 0x7c2534 +0xc; the park click handler 0x4879d0 returns before the tool dispatch); OpenTPW's speed pause keeps the tool live, and the original's pause key P (0x40bf70 calls 0x409350(1), which also opens a window) is not shown to block or pass park clicks (0x4879d0 does not read the pause flag 0x786b84)"),
		("PATH-014", "PATH-VARIANT: built straights and edges pick str1/str2 and edg1/edg2 by a hash of the cell (saved cells keep theirs); the original's chooser (tp.exe 0x535dd0) uses the second texture (2 becomes 19, 10 becomes 20) when byte 0x820ac0 is set (0x535fcc), and every call that reaches its end stores rand() & 1 there (CRT rand 0x67b5c0, store 0x53602c, seeded with GetTickCount at 0x54dddc), so each recomputation re-rolls from a shared clock-seeded generator and no per-cell rule exists"),
		("PATH-015", "QUEUE-TEXTURES: queue cells are drawn with QueueTex ground textures whose shape and turn follow decoded artwork and queue links; the original applies no QueueTex texture: its tile refresh 0x5365d0 sends a queue cell's class-2 result of the chooser 0x535dd0 (table 0x7630b0) to 0x5229e0, which places one of the queue models loaded by 0x522900 (quedead, questra, quebnd2, quebnd1, queend, quebin1, quebin2 .md2) turned by 360 minus the rotation, and gives the ground only the sentinel (0, 8, 0); OpenTPW does not draw these models")
	};
}
